        return "{\"name\":\"" + unique() + "\",\"email\":\"" + unique() + "\",\"active\":true,\"createdAt\":\"2024-01-01T00:00:00Z\"}";
    }

    // Runs inside the calling test, so it inherits that test's @TestSecurity principal.
    private static String createUser() {
        Object id = given().contentType(ContentType.JSON).body(bodyUser())
            .when().post("/users")
            .then().statusCode(201)
            .extract().path("id");
        return id.toString();
    }

    private static String bodyPost() {
        return "{\"title\":\"" + unique() + "\",\"body\":\"" + unique() + "\",\"published\":true}";
    }

